INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (1, '隆基再度入选标普全球能源2026年度Tier 1清洁能源技术企业榜单', '隆基再度入选标普全球能源2026年度Tier 1清洁能源技术企业榜单 隆基新闻 2026.7.13 近日，标普全球能源（S&P Global Energy）正式发布第二届年度Tier 1清洁能源技术企业榜单。继2025年首届榜单即上榜后，隆基绿能再度入选太阳能光伏组件类别，成为全球获此认可的15家光伏组件供应商之一。 标普全球能源凭借其独特的跨部门协同能力，为该榜单构建了一套严谨明确的六维标准评估体系，涵盖市场影响力与累计设备出货量、年度市场份额、规模、全球产能布局、关键财务指标表现、可持续发展因素等多个维度，对五…', '隆基再度入选标普全球能源2026年度Tier 1清洁能源技术企业榜单 隆基新闻 2026.7.13 近日，标普全球能源（S&P Global Energy）正式发布第二届年度Tier 1清洁能源技术企业榜单。继2025年首届榜单即上榜后，隆基绿能再度入选太阳能光伏组件类别，成为全球获此认可的15家光伏组件供应商之一。 标普全球能源凭借其独特的跨部门协同能力，为该榜单构建了一套严谨明确的六维标准评估体系，涵盖市场影响力与累计设备出货量、年度市场份额、规模、全球产能布局、关键财务指标表现、可持续发展因素等多个维度，对五大产品类别中的供应商进行全面衡量。值得关注的是，今年评估首次将信用风险纳入核心财务维度，以RiskGauge™ 评分作为关键参照，在行业经历周期波动的当下尤显分量。 对于这一评估体系，标普全球能源清洁能源技术与供应链负责人Edurne Zoco博士表示：“标普全球能源Tier 1榜单的独特之处，在于其所依托数据的广度和深度。我们不止关注企业的市场份额，还借助标普全球在市场领导力、财务表现和可持续发展方面的专有数据，对供应商实力进行更加全面的评估与呈现。我们的Tier 1榜单旨在帮助优秀的清洁能源技术供应商在竞争激烈的市场中脱颖而出，同时为开发商和投资者提供更加清晰的参考依据，以助其识别拥有良好业绩记录并具备更坚实长期发展基础的企业。” 标普全球能源Tier 1清洁能源技术企业榜单并非排名，而是依据严谨的评估方法论甄选出的优质企业名录，按产品类别以企业英文名称字母顺序排列。参评企业从太阳能光伏组件、太阳能光伏逆变器、电池储能系统、储能电芯和风机五大类别中筛选产生，均为各类别上一年度全球出货量或装机量排名前30的公司。 在此框架下，对隆基而言，再度入选这一榜单，意味着在全球清洁能源项目融资、大型电站招标以及产业链责任审核中，公司的竞争实力与品牌信誉再次获得权威第三方的背书，也向合作伙伴传递出明确的信赖信号。 同时，该榜单也是清洁能源技术行业中首个将可持续发展作为关键评估标准的供应商名录，每年更新一次，以动态反映供应商在各评估维度上的发展变化。隆基连续获得Tier 1认可的背后，正是对产品可靠性、供应链透明度与可追溯性的长期坚守，以及将企业社会责任深度融入运营体系的持续实践。 面向未来，在清洁能源加速成为全球基础设施关键底座的大时代里，隆基将继续以稳健、可靠、创新的姿态，与合作伙伴并肩，为世界输送源源不断的绿色能源与长期价值。 关于隆基 作为全球领先的绿色能源科技公司，隆基绿能聚焦科技创新，构建起光伏、储能与氢能三大核心引擎，为全球客户提供安全、经济、绿色的能源解决方案。公司倡导可持续发展，致力于让人人享有可负担的清洁能源。通过绿色电力、储能系统和氢能生产的有机衔接，实现发电、储电、用电全链条的清洁能源覆盖，构建真正普惠可达的清洁能源生态。 如欲了解更多信息，欢迎访问：https://www.longi.com/cn/ 上一条 下一条', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-13 00:00:00', '2026-07-13 22:58:15', '2026-07-13 23:58:48', 0, NULL, 'ENTERPRISE', 'EXTERNAL_NEWS', 'ENTERPRISE_SITE', '隆基绿能', 'https://www.longi.com/cn/news/spglobal-tier1-2026/', '4a650348ae1179bb171c27c2e46ca359042414f19d2a7848f6ca60f7b89c93e4', '2026-07-13 00:00:00', '2026-07-13 22:58:18', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (2, '从GW级电站到配电台区：全栈隆基LONGi ONE，终结光储拼凑时代', '从GW级电站到配电台区：全栈隆基LONGi ONE，终结光储拼凑时代 隆基新闻 2026.6.4 在SNEC 2026展会上，隆基正式发布了面向工商业台区储能的Hi-MO One光储一体解决方案，将“全栈隆基 LONGi ONE”的技术逻辑延伸至配电网末梢环节。 这些问题不体现于设备铭牌参数，却持续压低配网资产的实际运行效率。隆基的应对策略并非为每个问题单独增配治理设备，而是通过一套原生融合的系统，从源头对电能质量问题进行统一管理。 效率的起点:一体化集成的系统架构 Hi-MO One光储一体机正是这一解法的硬件载…', '<h1>从GW级电站到配电台区：全栈隆基LONGi ONE，终结光储拼凑时代</h1>  隆基新闻 2026.6.4\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul>\n<p>在SNEC 2026展会上，隆基正式发布了面向工商业台区储能的Hi-MO One光储一体解决方案，将“全栈隆基 LONGi ONE”的技术逻辑延伸至配电网末梢环节。</p>\n<p>这些问题不体现于设备铭牌参数，却持续压低配网资产的实际运行效率。隆基的应对策略并非为每个问题单独增配治理设备，而是通过一套原生融合的系统，从源头对电能质量问题进行统一管理。</p>\n<p><strong>效率的起点:一体化集成的系统架构</strong></p>\n<p>Hi-MO One光储一体机正是这一解法的硬件载体。其内部采用全栈自研架构，实现深度协同，并非“电池柜+逆变器+控制屏”的简单拼装，而是一台出厂前已完成系统联调的完整设备。</p>\n<p><strong>硬件融合：消除设备边界，重构能量流路径</strong></p>\n<p>传统台区储能方案将逆变器、BMS、EMS分设于不同物理模块，模块间通过工业协议通信，存在固有的协议转换延迟（通常在100毫秒量级）和状态失步风险。Hi-MO One打破这一物理边界，将PCS、BMS、EMS及配网接口单元集成于同一硬件平台，能量流在设备内部完成闭环，从硬件层面确立了系统效率的先天优势。</p>\n<p><strong>感知控制：毫秒级闭环，从“被动响应”到“主动预判”</strong></p>\n<p>该架构的核心优势在于全栈自研带来的感知、决策、执行闭环协同能力。内部5S架构原生融合，消除了异构拼凑方案中多设备间的通信延迟与协议转换导致的响应滞后。Hi-MO One内置三相实时感知单元，采样频率达50kHz，可在单个工频周期（20ms）内完成电压越限判定和功率调度决策。</p>\n<p>相较于依赖外部EMS下发指令的方案（响应时间通常在500毫秒至2秒），本地边缘控制将系统响应速度提升一个数量级。这意味着当光伏反送导致电压瞬态越限时，Hi-MO One能在问题扩散前完成功率吸收，而非事后被动调节。</p>\n<p><strong>协同算法：多目标优化引擎，平衡效率与安全的动态边界</strong></p>\n<p>系统需在同一时刻权衡三相不平衡补偿、电压支撑、峰谷套利和电池健康管理（SOC均衡与温度保护）等多个相互竞争的目标。</p>\n<p>Hi-MO One采用基于模型预测控制（MPC）的滚动优化框架：以分钟级预测窗口，结合台区历史负荷曲线、光伏出力预测和电价信号，动态生成最优功率调度序列。当多目标之间发生约束冲突时（如电压支撑与峰谷套利对功率方向的要求相反），系统依据预设优先级自动裁决，将电网安全约束置于经济效益之上，确保台区运行始终处于安全包络之内。这一算法层面的精细化处理，是系统在复杂工况下维持“巅峰效率”的核心支撑。</p>\n<p><strong>工况验证：四层架构的完整技术闭环</strong></p>\n<p>以典型农村台区为例，一台Hi-MO One接入配电变压器低压侧后，其内部感知单元开始实时监测台区三相电压与潮流方向。当午间光伏大发导致某相电压越上限时，系统在毫秒级时间内将过剩功率导入储能电池，而非被动等待逆变器降额或脱网；当傍晚负荷高峰拉低末端电压时，储能立即转为放电模式，向特定相精准注入有功功率，将电压拉回合格区间。整个过程无需人工干预，也不依赖上一级调度指令，完全由本地控制逻辑自主完成。</p>\n<p>硬件融合奠定效率基础，边缘感知实现快速响应，协同算法平衡多目标冲突，工况验证将性能落实为可量化改善——这四个层级环环相扣，形成完整系统闭环，也正是“巅峰效率”从概念走向工程实现的完整路径。</p>\n<p><strong>价值的落点:可量化的运行改善</strong></p>\n<p>对工商业用户而言，“巅峰效率”最终必须转化为可量化的运行改善。在城市充电站场景，多台区柔性互联技术将若干相邻台区的OneOS系统连接为一个共享储能池。当某一台区因多车同时快充出现短时功率尖峰时，相邻台区的储能单元可瞬间提供功率支援，避免该台区变压器过载，同时降低基本电费计费需量。</p>\n<p>在高光伏渗透率的农村台区，毫秒级响应机制确保反送过压被及时吸收，使台区内的分布式光伏真正实现“应发尽发”，不再因电压约束而被动弃光。据测算，这一能力可将台区年均弃光率从典型异构方案的5%-8%压缩至接近零，直接提升绿电就地消纳水平。</p>\n<p>上述场景中的每一次优化，均体现为电能的充分消纳、电压波动的快速平抑以及投资回收期的有效缩短。</p>\n<p><strong>将“最后一公里”转化为效率释放的起点</strong></p>\n<p>配电网的末梢，是电力系统连接终端用户的最终环节。当行业普遍将“最后一公里”视为问题集中区域时，隆基储能选择将其重新定义为效率释放的前沿节点。</p>\n<p>从大型电站到工商业台区，隆基的核心逻辑始终一致：提供一套完整的、高效协同的系统，而非交由客户自行集成的分散设备。当光储融合的高效运行模式从GW级电站延伸至每一个配电台区，工商业储能的价值逻辑正在被重新定义。</p>\n<p><strong>关于隆基</strong></p>\n<p>作为全球领先的绿色能源科技公司，隆基绿能聚焦科技创新，构建起光伏、储能与氢能三大核心引擎，为全球客户提供安全、经济、绿色的能源解决方案。公司倡导可持续发展，致力于让人人享有可负担的清洁能源。通过绿色电力、储能系统和氢能生产的有机衔接，实现发电、储电、用电全链条的清洁能源覆盖，构建真正普惠可达的清洁能源生态。</p>\n<p>如欲了解更多信息，欢迎访问：<a href=\"https://www.longi.com/cn/\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.longi.com/cn/</a></p>\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul> <a href=\"https://www.longi.com/cn/news/wood-mackenzie/\" rel=\"noopener noreferrer\" target=\"_blank\"> 上一条 </a> <a href=\"https://www.longi.com/cn/news/longi-hi-roof-launch/\" rel=\"noopener noreferrer\" target=\"_blank\"> 下一条 </a>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-06-04 00:00:00', '2026-07-13 22:58:16', '2026-07-14 18:36:42', 0, NULL, 'ENTERPRISE', 'EXTERNAL_NEWS', 'ENTERPRISE_SITE', '隆基绿能', 'https://www.longi.com/cn/news/longi-one-snec/', 'a3a40cc937e37fc95d64c3f347329cc365ad820ee882166699d1ff0437386ca9', '2026-06-04 00:00:00', '2026-07-14 18:36:56', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (3, '隆基太阿组件以澎湃绿电打造“光伏治沙”新标杆', '隆基太阿组件以澎湃绿电打造“光伏治沙”新标杆 案例实践 2026.7.1 作为国家在沙漠、戈壁、荒漠地区重点建设的大型风光基地项目，这座位于我国西北的某800MW光伏电站，规模化采用了960MW隆基太阿组件，在“光伏+治沙”融合开发模式中树立了高效、高可靠的技术典范。 项目地位于沙漠边缘，具有极端干旱、强日照、高风沙及昼夜温差大等气候特点，严苛的外在自然条件对光伏电站的设计、建设到长期稳定运行提出了极大挑战。经过多次方案比选与反复测算，项目最终选用了隆基专为“沙戈荒”场景打造的太阿组件，其全生命周期的卓越可靠性与优…', '<h1>隆基太阿组件以澎湃绿电打造“光伏治沙”新标杆</h1>  案例实践 2026.7.1\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul>\n<p>作为国家在沙漠、戈壁、荒漠地区重点建设的大型风光基地项目，这座位于我国西北的某800MW光伏电站，规模化采用了960MW隆基太阿组件，在“光伏+治沙”融合开发模式中树立了高效、高可靠的技术典范。</p>\n<p>项目地位于沙漠边缘，具有极端干旱、强日照、高风沙及昼夜温差大等气候特点，严苛的外在自然条件对光伏电站的设计、建设到长期稳定运行提出了极大挑战。经过多次方案比选与反复测算，项目最终选用了隆基专为“沙戈荒”场景打造的太阿组件，其全生命周期的卓越可靠性与优异发电性能将为行业打造“光伏治沙”新标杆。</p>\n<p><strong>硬核防护，无惧极端工况与风沙考验</strong></p>\n<p>针对沙漠地区频发的强风与沙尘侵袭，太阿组件在结构与材料上进行了定制化开发设计。其搭载的“锋锐边框”具备高强载荷性能，与常规铝合金基材相比，锋锐边框材料强度提升150%以上，可有效应对极端工况下的变形问题，保障电站在狂风肆虐下的结构安全。</p>\n<p>据隆基实验室实测，太阿组件正面在机器加压到最大压强9999Pa时仍可成功通过，组件外观、绝缘和湿漏电情况均无异常，突破了行业极限。而组件背面的最大压强也可高达4000Pa以上，展现出超预期的超强载荷能力。综合来看，该产品可有效提升大风、暴雪等环境下的载荷性能，保证极端条件下的持续稳定发电。</p>\n<p><strong>高效高可靠，全生命周期释放澎湃绿电</strong></p>\n<p>去年9月上市的Hi-MO 9太阿组件，基于隆基自主研发的HPBC 2.0技术平台，其正面无栅线设计最大化了太阳光的吸收面积，结合优异的弱光响应与更优的温度系数，确保组件在沙漠高温及早晚弱光时段依然保持高效发电。此外，Hi-MO 9太阿组件配备的“逸尘玻璃”通过优化表面膜层，可显著降低沙尘附着与积灰概率，相比常规组件，可在干旱多沙环境中带来额外的发电增益。同时，也可有效降低电站的清洗频率与日常运维成本。</p>\n<p>在“光伏+治沙”模式下，光伏板下的沙生植物、户外的鸟粪、灰尘等会不可避免地对组件产生局部阴影遮挡。基于高效BC电池结构，Hi-MO 9太阿组件能够有效抑制组件的热斑效应。其更低的热斑温度，也从根源上缓解了因局部过热引发的材料老化、功率衰减乃至潜在火灾风险，为电站25年以上的持久可靠运行提供了坚实保障。</p>\n<p>截至目前，来自多家国际权威技术服务机构的数据报告一致表明：相较于当前市场主流的TOPCon组件，Hi-MO 9在全球范围内实现稳定的单瓦发电量提升，增益幅度介于1.21%至3.92%之间，部分场景下表现尤为突出。BC技术已被验证为同时实现高发电收益与极致安全的理想解决方案。</p>\n<p>科技至美，价值致远。未来，隆基绿能将持续深耕技术创新，将更多更优质的光伏产品与区域生态治理深度融合，为全球荒漠地区打造更加可靠坚实的“绿色铠甲”，也为全球能源转型提供更具价值的解决方案与技术范本。</p>\n<p><strong>关于隆基</strong></p>\n<p>作为全球领先的绿色能源科技公司，隆基绿能聚焦科技创新，构建起光伏、储能与氢能三大核心引擎，为全球客户提供安全、经济、绿色的能源解决方案。公司倡导可持续发展，致力于让人人享有可负担的清洁能源。通过绿色电力、储能系统和氢能生产的有机衔接，实现发电、储电、用电全链条的清洁能源覆盖，构建真正普惠可达的清洁能源生态。</p>\n<p>如欲了解更多信息，欢迎访问：<a href=\"https://www.longi.com/cn/\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.longi.com/cn/</a></p>\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul> <a href=\"https://www.longi.com/cn/news/longi-acm-cell-mass-production/\" rel=\"noopener noreferrer\" target=\"_blank\"> 上一条 </a> <a href=\"https://www.longi.com/cn/news/sign-mou-saudi-water-authority/\" rel=\"noopener noreferrer\" target=\"_blank\"> 下一条 </a>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-01 00:00:00', '2026-07-13 22:58:16', '2026-07-14 18:36:42', 0, NULL, 'ENTERPRISE', 'EXTERNAL_NEWS', 'ENTERPRISE_SITE', '隆基绿能', 'https://www.longi.com/cn/news/tai-a-modules-longi-solar-sand-control/', 'b61f2467af6a55e4209758ad249229c118b9eb9d651160dd9ce0d2e177f4e3da', '2026-07-01 00:00:00', '2026-07-14 18:36:56', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (4, '通车！LONGi Hi ROOF S护航西安东站，屋顶光伏蓄势待发', '通车！LONGi Hi ROOF S护航西安东站，屋顶光伏蓄势待发 案例实践 2026.6.30 绿能相伴，西北最大综合交通枢纽即将开启绿电时代 2026年6月30日，随着首趟列车驶离西安东站。这座13台27线、年设计客流量近四千万人次的西北最大综合交通枢纽，正式开门迎客。站台之上，人潮涌动；站房屋顶，来自隆基绿能的7.25MW光伏矩阵已准备就绪。 作为国家“八纵八横”高铁网和陕西“米”字型高铁网的重要枢纽，西安东站的开通，意味着西北铁路网的一次关键落子。而它的另一重身份——西北首个大规模应用自发电绿电的特大型枢纽…', '<h1>通车！LONGi Hi ROOF S护航西安东站，屋顶光伏蓄势待发</h1>  案例实践 2026.6.30\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul>\n<p><strong>绿能相伴，西北最大综合交通枢纽即将开启绿电时代</strong></p>\n<p>2026年6月30日，随着首趟列车驶离西安东站。这座13台27线、年设计客流量近四千万人次的西北最大综合交通枢纽，正式开门迎客。站台之上，人潮涌动；站房屋顶，来自隆基绿能的7.25MW光伏矩阵已准备就绪。</p>\n<p>作为国家“八纵八横”高铁网和陕西“米”字型高铁网的重要枢纽，西安东站的开通，意味着西北铁路网的一次关键落子。而它的另一重身份——西北首个大规模应用自发电绿电的特大型枢纽，同样在“十五五”开局之年，写下了浓墨重彩的一笔。</p>  *西安东站建筑光伏项目（图片来自央视新闻） \n<p>公共建筑，尤其是特大型交通枢纽，光伏安装的门槛远比厂房、仓库严苛。人流动线密集，消防规范极严，异形屋面复杂，多专业交叉施工，每一项都是考验。更关键的是，公共建筑自带“城市名片”属性，光伏不能只是功能性的设备叠加，还得过美学这一关。铁路系统更是对安全零容忍。能在消防、结构、美学、运维的多重约束下站稳脚跟的公建光伏案例，凤毛麟角。</p>\n<p>而西安东站，恰恰从一开始就把光伏写进了设计蓝图。但问题在于，东站的屋顶，是那个“最难啃的骨头”。</p>\n<p>十万平方米菱形双曲面屋顶，选用铝镁锰板。轻薄、延展性好，能拗出“八百里秦川”的恢宏气势，但热膨胀系数远高于普通金属屋面。西安冬夏温差与风振让金属屋面持续“呼吸”，传统打钉穿透的安装方式，不仅破坏防水，更经不起数年后金属疲劳的考验。建筑美学要保留双曲面，工程安全又不允许打钉。两条红线之间，几乎没有回旋余地。</p>\n<p>面对这道难题，隆基团队采用<strong>“胶粘+夹具”双保险方案</strong>。胶粘提供高弹性缓冲以“柔”克刚，吸收变形；夹具负责长期承载以“刚”护体，协同工作。系统全线阻燃，满足建筑与光伏行业双A级防火，而风洞测试更验证了系统的稳定性。</p>\n<p>不止于此。作为西安新的东部门户，建筑造型本身就是城市名片。项目选用的LONGi Hi ROOF S四防发电系统，搭载隆基HPBC2.0电池，全屏无框设计，正面无栅线。更以“以直代曲、随波铺设”的方式贴合双曲面，横装跨度小，现场逐块调平。光伏与建筑曲面融为一体，波浪舒展，发电的同时不失地标之美。</p>\n<p>安全、美观、发电效率，同时达标，并且经得起铁路系统全面论证。这也是陕西国铁经营服务有限公司最终选择隆基的原因。</p>\n<p>据测算，25年生命周期内，西安东站建筑光伏系统将贡献约1.9亿度绿电，相当于节约标准煤5.9万吨，减排二氧化碳18.6万吨，等效植树41万棵。所发绿电覆盖车站照明、空调、电梯等日常用电需求。这座年客流量近四千万人次的枢纽，正在成为绿色车站的标杆。</p>\n<p>但它的价值不止于一座车站的节能账本。西北首个自发绿电特大型枢纽的诞生，验证了光伏与轨交、光伏与公建在超高难度场景下的可行性。作为LONGi Hi ROOF S在双曲面上的首次大规模应用，也是其在公共建筑领域首个“胶粘+机械连接”的落地项目，西安东站经受住了铁路系统的全面论证，为大型公共建筑的绿色低碳转型提供了一条可验证、可复制的技术路径。</p>\n<p>当西十高铁让西安的肉夹馍和十堰的三合汤融入同一顿午餐，旅客们在站台上奔向下一站山海；而此刻，屋顶的光伏矩阵正静默地迎接属于它的“通车”。西安东站不仅是一座枢纽的落成，它用每一度绿电证明，公共建筑的碳中和未来，并非遥不可及，而是已经稳稳地站在这片“秦川”之上。</p>\n<p><strong>隆基光建，让每一寸建筑都天然发电。</strong></p>\n<p><strong>关于隆基</strong></p>\n<p>作为全球领先的绿色能源科技公司，隆基绿能聚焦科技创新，构建起光伏、储能与氢能三大核心引擎，为全球客户提供安全、经济、绿色的能源解决方案。公司倡导可持续发展，致力于让人人享有可负担的清洁能源。通过绿色电力、储能系统和氢能生产的有机衔接，实现发电、储电、用电全链条的清洁能源覆盖，构建真正普惠可达的清洁能源生态。</p>\n<p>如欲了解更多信息，欢迎访问：<a href=\"https://www.longi.com/cn/\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.longi.com/cn/</a></p>\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul> <a href=\"https://www.longi.com/cn/news/sign-mou-saudi-water-authority/\" rel=\"noopener noreferrer\" target=\"_blank\"> 上一条 </a> <a href=\"https://www.longi.com/cn/news/longi-pv-master-digital-with-purpose/\" rel=\"noopener noreferrer\" target=\"_blank\"> 下一条 </a>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-06-30 00:00:00', '2026-07-13 22:58:16', '2026-07-14 18:36:43', 0, NULL, 'ENTERPRISE', 'EXTERNAL_NEWS', 'ENTERPRISE_SITE', '隆基绿能', 'https://www.longi.com/cn/news/longi-hi-roof-s-xiandong-railway-station/', '8072ac4a44c99ed9034076cba491eb6792587d144cacd17d88129c2b3ddbf5e4', '2026-06-30 00:00:00', '2026-07-14 18:36:56', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (5, '隆基绿能与沙特水务局签署战略备忘录，推进沙特水务行业可再生能源整合与数字化转型', '隆基绿能与沙特水务局签署战略备忘录，推进沙特水务行业可再生能源整合与数字化转型 可持续发展 2026.6.30 2026年6月28日在沙特阿拉伯吉达，隆基绿能科技股份有限公司（隆基绿能）在2026年沙特水务周期间与沙特水务局（SWA）签署了一项战略备忘录。该协议由环境、水与农业部（MEWA）副部长曼苏尔·穆沙伊蒂阁下见证签署，沙特水务局研究与前沿技术副总裁、董事会成员塔里格·盖法里阁下与隆基绿能中东地区总裁金剑先生共同签署。 ﻿该合作旨在根据沙特2030愿景，推进沙特阿拉伯水务生产、处理和分配基础设施中的可再生能源…', '<h1>隆基绿能与沙特水务局签署战略备忘录，推进沙特水务行业可再生能源整合与数字化转型</h1>  可持续发展 2026.6.30\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul>\n<p>2026年6月28日在沙特阿拉伯吉达，隆基绿能科技股份有限公司（隆基绿能）在2026年沙特水务周期间与沙特水务局（SWA）签署了一项战略备忘录。该协议由环境、水与农业部（MEWA）副部长曼苏尔·穆沙伊蒂阁下见证签署，沙特水务局研究与前沿技术副总裁、董事会成员塔里格·盖法里阁下与隆基绿能中东地区总裁金剑先生共同签署。</p>\n<p>﻿该合作旨在根据沙特2030愿景，推进沙特阿拉伯水务生产、处理和分配基础设施中的可再生能源整合与数字化转型。</p>\n<p>这项战略合作伙伴关系建立了涵盖四个关键领域的合作框架：</p>\n<p><strong>1. 清洁能源整合</strong></p>\n<ul>\n <li>水务基础设施的太阳能光伏部署</li>\n <li>绿色氢和储能解决方案</li>\n</ul>\n<p><strong>2. 数字转型</strong></p>\n<ul>\n <li>人工智能驱动的水系统优化</li>\n <li>水网络的智能监测和数据分析</li>\n</ul>\n<p><strong>3. 产业本地化</strong></p>\n<ul>\n <li>技术本地化和供应链发展</li>\n <li>本地制造机会探索</li>\n</ul>\n<p><strong>4. 人力资本与创新</strong></p>\n<ul>\n <li>沙特国民的劳动力培训项目</li>\n <li>联合研发和试点示范项目</li>\n</ul>\n<p>该备忘录是推进沙特水务行业综合清洁能源解决方案的重要一步。它反映了全球技术提供商与沙特机构之间日益增长的合作，以支持沙特在2030愿景下的脱碳和本地化目标。</p>\n<p>塔里格表示：“在选择隆基绿能时，我们考虑到其在太阳能领域的强大技术能力以及其对支持沙特王国能源转型目标的承诺。此次合作将助力我们提升沙特水务基础设施的可持续性和效率。”</p>\n<p>金剑表示：“此次合作体现了隆基绿能对中东地区的长期承诺，以及其在为关键基础设施提供清洁能源解决方案方面的作用。我们期待与沙特水务局合作，探索可扩展的太阳能和氢能应用，以支持沙特王国的可持续发展目标。”</p>\n<p>该备忘录进一步强化了隆基绿能对支持中东地区清洁能源转型和关键基础设施部门脱碳的承诺。</p>\n<p><strong>关于沙特水务局SWA</strong></p>\n<p>沙特水务局是沙特政府机构，负责规范和发展沙特王国的水务部门，监督水的生产、处理、传输和分配。沙特水务局致力于确保水的可持续性和安全性，并通过创新和战略合作伙伴关系推动高效和低碳运营。</p>\n<p><strong>关于隆基</strong></p>\n<p>作为全球领先的绿色能源科技公司，隆基绿能聚焦科技创新，构建起光伏、储能与氢能三大核心引擎，为全球客户提供安全、经济、绿色的能源解决方案。公司倡导可持续发展，致力于让人人享有可负担的清洁能源。通过绿色电力、储能系统和氢能生产的有机衔接，实现发电、储电、用电全链条的清洁能源覆盖，构建真正普惠可达的清洁能源生态。</p>\n<p>如欲了解更多信息，欢迎访问：<a href=\"https://www.longi.com/cn/\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.longi.com/cn/</a></p>\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul> <a href=\"https://www.longi.com/cn/news/tai-a-modules-longi-solar-sand-control/\" rel=\"noopener noreferrer\" target=\"_blank\"> 上一条 </a> <a href=\"https://www.longi.com/cn/news/longi-hi-roof-s-xiandong-railway-station/\" rel=\"noopener noreferrer\" target=\"_blank\"> 下一条 </a>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-06-30 00:00:00', '2026-07-13 22:58:16', '2026-07-14 18:36:43', 0, NULL, 'ENTERPRISE', 'EXTERNAL_NEWS', 'ENTERPRISE_SITE', '隆基绿能', 'https://www.longi.com/cn/news/sign-mou-saudi-water-authority/', '0640af84c70baf8d58c1b4d62bfa8ce2e1376dd4b1e7604f5cf4a13d751e79a5', '2026-06-30 00:00:00', '2026-07-14 18:36:56', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (6, '荣获“Digital with Purpose”大奖，隆基 PVMaster 树立光伏数智化行业标杆', '荣获“Digital with Purpose”大奖，隆基 PVMaster 树立光伏数智化行业标杆 隆基新闻 2026.6.29 近日，由全球赋能可持续发展倡议组织（GeSI）与深圳市加中创新中心联合主办的2026数字向善大会（Digital With Purpose Summit）在深圳盐田万科国际会议中心举办。此次大会会以“数字向善：构建可持续未来的数字基石”为主题，旨在联动国际组织、跨国企业及政策制定者，多维度探讨数字技术赋能可持续发展的全球趋势、挑战与机遇。DWP全球奖项由GeSI发起，在生物多样性、气候…', '<h1>荣获“Digital with Purpose”大奖，隆基 PVMaster 树立光伏数智化行业标杆</h1>  隆基新闻 2026.6.29\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul>\n<p>近日，由全球赋能可持续发展倡议组织（GeSI）与深圳市加中创新中心联合主办的2026数字向善大会（Digital With Purpose Summit）在深圳盐田万科国际会议中心举办。此次大会会以“数字向善：构建可持续未来的数字基石”为主题，旨在联动国际组织、跨国企业及政策制定者，多维度探讨数字技术赋能可持续发展的全球趋势、挑战与机遇。DWP全球奖项由GeSI发起，在生物多样性、气候、教育、健康与福祉，以及智慧城市等五个不同类别中评选出杰出解决方案，旨在表彰那些将技术创新与现实可持续发展影响力相结合的典范性数字解决方案。隆基绿能研发的数智产品PVMaster凭借其在数字技术赋能可持续发展领域的卓越表现，荣获“Digital with Purpose”数字向善气候类别全球年度奖项，作为气候类别中唯一获奖企业受邀参与了6月26日举办的颁奖盛典。</p>  GeSI首席执行官Luís Neves向隆基PVMaster负责人刘周宏颁发奖杯 \n<p>PVMaster是隆基绿能自主研发的一款分布式智能光伏电站设计平台，旨在解决传统光伏项目开发中流程繁琐、效率低下、依赖资深工程师经验等行业痛点。该平台将原本需要两三天、在多款软件间切换的复杂流程，整合为“一站式”解决方案，涵盖从卫星图初勘、3D建模、组件自动排布，到电气设计、发电量测算、经济性分析及报告生成的全链条功能，最快可在十分钟内完成方案输出。</p>\n<p>其核心价值在于“提效”与“开放”。PVMaster内置对标国际标准的算法与庞大的设备数据库，显著降低了设计门槛，让非专业人员也能快速上手；同时，平台不绑定任何硬件品牌，面向全行业开放，真正践行了“以开放生态推动全球绿能普及”的理念。PVMaster上线至今，近 3 万个项目、16 吉瓦装机，覆盖六大洲，对应每年约1,100 万吨碳减排。未来，我们将数字化能力从项目开发延伸到电站运营与能源管理。</p>\n<p>此次荣获“Digital with Purpose”大奖，不仅是对PVMaster产品技术实力的肯定，更是对隆基绿能以数智化驱动能源转型、坚持开放合作战略的高度认可。隆基绿能正将数字化能力从项目开发环节向电站运营与能源管理延伸，持续为全球零碳未来提供更高效、更智能的解决方案，以数智之力，共赴零碳未来。</p>\n<p><strong>关于隆基</strong></p>\n<p>作为全球领先的绿色能源科技公司，隆基绿能聚焦科技创新，构建起光伏、储能与氢能三大核心引擎，为全球客户提供安全、经济、绿色的能源解决方案。公司倡导可持续发展，致力于让人人享有可负担的清洁能源。通过绿色电力、储能系统和氢能生产的有机衔接，实现发电、储电、用电全链条的清洁能源覆盖，构建真正普惠可达的清洁能源生态。</p>\n<p>如欲了解更多信息，欢迎访问：<a href=\"https://www.longi.com/cn/\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.longi.com/cn/</a></p>\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul> <a href=\"https://www.longi.com/cn/news/longi-hi-roof-s-xiandong-railway-station/\" rel=\"noopener noreferrer\" target=\"_blank\"> 上一条 </a> <a href=\"https://www.longi.com/cn/news/hi-mo-9-prime-launch-intersolar-europe-2026/\" rel=\"noopener noreferrer\" target=\"_blank\"> 下一条 </a>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-06-29 00:00:00', '2026-07-13 22:58:17', '2026-07-14 18:36:43', 0, NULL, 'ENTERPRISE', 'EXTERNAL_NEWS', 'ENTERPRISE_SITE', '隆基绿能', 'https://www.longi.com/cn/news/longi-pv-master-digital-with-purpose/', '8b468b10fd0b734f1f15e1d656f36e01cac7bf5ff075c65632650c0ca592f364', '2026-06-29 00:00:00', '2026-07-14 18:36:57', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (7, '隆基Hi-MO 9至臻 重磅亮相Intersolar Europe 2026，高效BC重塑电站资产价值', '隆基Hi-MO 9至臻 重磅亮相Intersolar Europe 2026，高效BC重塑电站资产价值 隆基新闻 2026.6.24 慕尼黑时间6月23日，隆基绿能在Intersolar Europe 2026展会重磅发布了Hi-MO 9至臻（Hi-MO 9 Prime）系列组件。作为隆基HPBC2.0技术的全新旗舰产品，Hi-MO 9至臻组件精准契合了集中式项目对土地集约利用、长期运行可靠性、全生命周期高收益三大核心诉求，组件功率最高可达680W，光电转换效率达25.17%，为全球光伏产业再次树立高效发电新标杆。…', '<h1>隆基Hi-MO 9至臻 重磅亮相Intersolar Europe 2026，高效BC重塑电站资产价值</h1>  隆基新闻 2026.6.24\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul>\n<p>慕尼黑时间6月23日，隆基绿能在Intersolar Europe 2026展会重磅发布了Hi-MO 9至臻（Hi-MO 9 Prime）系列组件。作为隆基HPBC2.0技术的全新旗舰产品，Hi-MO 9至臻组件精准契合了集中式项目对土地集约利用、长期运行可靠性、全生命周期高收益三大核心诉求，组件功率最高可达680W，光电转换效率达25.17%，为全球光伏产业再次树立高效发电新标杆。</p>\n<p>全新推出的Hi-MO 9至臻组件，基于隆基高效HPBC2.0技术打造，标志着Hi-MO 9产品家族的又一次重大技术跨越与价值升级。该产品进一步优化了平台的功率密度与结构布局，通过将所有电极触点置于电池背面，实现组件正面零遮光，从而最大化吸收太阳光，为全球集中式电站创造更可观的长期综合收益。</p>\n<p><strong>高功率适配标准版型，实现装机量与发电收益双跃升</strong></p>\n<p>随着全球光伏规模化建设提速，地面电站普遍缩小阵列行距，以此提升单位土地装机规模。但高密度排布易产生阵列互相遮挡、板面辐照不均等问题，直接造成电站发电量折损。</p>\n<p>Hi-MO 9至臻系列针对性解决了电站排布的核心痛点，沿用经过海量地面项目验证、适配性更强的标准组件版型：2382 × 1134 × 30mm。相较其他常规组件，该尺寸既能大幅缓解阵列遮挡损耗，又可同步提升单位土地装机容量。据测算，在典型项目模型中，在相同土地面积和阵列排布方案下，Hi-MO 9至臻产品可使总装机容量提升4.62%。</p>\n<p><strong>&nbsp;</strong></p>\n<p><strong>自研STAC技术，为电站全生命周期可靠性保驾护航</strong></p>\n<p>极致可靠性是Hi-MO 9至臻产品设计的另一核心亮点。该组件搭载了隆基自研的STAC（Selective Temperature Alloy Connection）技术，可最大限度降低制造过程中的局部热应力，显著提升组件的长期稳定性。除此之外，Hi-MO 9至臻系列还具备卓越的抗局部阴影遮挡性能，可为电站全生命周期高收益保驾护航。其高效BC电池结构，能够大幅降低由阵列间遮挡、灰尘、落叶或其他临时遮挡物引起的热斑风险。当单片电池被遮挡时，与传统非BC组件相比，Hi-MO 9至臻组件可将功率损失降低70%以上，能够长久稳定输出更可靠的绿色电力。</p>\n<p>对于全球地面电站而言，这种工程级的极致可靠性是保障其全生命周期价值的关键。随着时间推移，组件热斑、隐裂及电池片应力等传统风险往往会逐步增高，Hi-MO 9至臻系列可有效降低这些组件生命周期的常见风险，为电站资产所有者和相关方提供长期高可靠的商业收益与价值。</p>\n<p>Hi-MO 9至臻系列的重磅发布，将为全球电站资产价值跃升与长效安全带来首屈一指的行业范本。未来，隆基将持续深耕BC技术创新，以更具价值的光伏产品和解决方案，为光储时代的能源变革注入强劲动能。</p>\n<p><strong>关于隆基</strong></p>\n<p>作为全球领先的绿色能源科技公司，隆基绿能聚焦科技创新，构建起光伏、储能与氢能三大核心引擎，为全球客户提供安全、经济、绿色的能源解决方案。公司倡导可持续发展，致力于让人人享有可负担的清洁能源。通过绿色电力、储能系统和氢能生产的有机衔接，实现发电、储电、用电全链条的清洁能源覆盖，构建真正普惠可达的清洁能源生态。</p>\n<p>如欲了解更多信息，欢迎访问：<a href=\"https://www.longi.com/cn/\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.longi.com/cn/</a></p>\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul> <a href=\"https://www.longi.com/cn/news/longi-pv-master-digital-with-purpose/\" rel=\"noopener noreferrer\" target=\"_blank\"> 上一条 </a> <a href=\"https://www.longi.com/cn/news/intersolar-europe-2026-longi-one/\" rel=\"noopener noreferrer\" target=\"_blank\"> 下一条 </a>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-06-24 00:00:00', '2026-07-13 22:58:17', '2026-07-14 18:36:44', 0, NULL, 'ENTERPRISE', 'EXTERNAL_NEWS', 'ENTERPRISE_SITE', '隆基绿能', 'https://www.longi.com/cn/news/hi-mo-9-prime-launch-intersolar-europe-2026/', 'e209f4fab0e50eff908db85b33c986716b8781b36302829adf9103badb7e382f', '2026-06-24 00:00:00', '2026-07-14 18:36:57', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (8, '全栈整合终结拼凑时代，隆基以系统级安全重构欧洲光储选择', '全栈整合终结拼凑时代，隆基以系统级安全重构欧洲光储选择 隆基新闻 2026.6.24 当地时间6月23日，Intersolar Europe 2026在德国慕尼黑新国际展览中心开幕。隆基绿能携LONGi ONE全栈光储产品家族亮相，面向全球客户展示从高效BC光伏技术到储能系统5S核心部件（BMS、iCCS、EMS、TMS和PCS）深度整合的一体化解决方案。 从GWh级电站到工商业智慧绿电，从离网微网到并网协同，隆基以统一技术底座，覆盖全场景绿电需求，为欧洲光储行业摆脱“拼凑式隐患”、实现安全提质，提供系统性安全升级…', '全栈整合终结拼凑时代，隆基以系统级安全重构欧洲光储选择 隆基新闻 2026.6.24 当地时间6月23日，Intersolar Europe 2026在德国慕尼黑新国际展览中心开幕。隆基绿能携LONGi ONE全栈光储产品家族亮相，面向全球客户展示从高效BC光伏技术到储能系统5S核心部件（BMS、iCCS、EMS、TMS和PCS）深度整合的一体化解决方案。 从GWh级电站到工商业智慧绿电，从离网微网到并网协同，隆基以统一技术底座，覆盖全场景绿电需求，为欧洲光储行业摆脱“拼凑式隐患”、实现安全提质，提供系统性安全升级路径。 安全逻辑重构：被动响应转向主动防御 欧洲市场对储能安全的严苛标准，本质是对系统不可控因素的结构性防范。传统拼凑模式下，电芯、BMS、PCS、EMS分属不同供应商，安全责任割裂于多个合同边界，异构通信协议经多次转换带来的延迟与丢包风险，往往构成热失控的潜在隐患。 隆基全栈方案的核心差异在于，所有核心部件基于统一的底层架构协同设计。BMS采集的电芯数据无需经由第三方网关转换，可直接被EMS与PCS识别调用，消除协议适配层的响应盲区，使得故障判断从传统的“动作后保护”前移至“特征值异常即触发隔离”。截至当前，隆基全球累计部署储能超13GWh，运行期内确认零热失控事故。该安全记录基于全栈一体化架构带来的系统性容错能力，而非单一指标优化。 欧洲多场景实证：极端工况下的稳定运行 真实工况检验安全性的直接标尺。过去一年，隆基密集落地欧洲各国多个项目，横跨地中海盐雾腐蚀、高寒地区电网波动、岛屿微网孤岛运行等极端场景。 在意大利沿海光伏电站，储能系统与光伏高效协同，全栈方案经受住了高湿度、高盐雾环境的长期考验，实现全天候稳定并网运行； 在芬兰奥兰群岛太阳能园区，面对严寒气候与脆弱电网的双重挑战，储能系统承担快速频率调节与黑启动备用职能，为孤岛微网筑牢供电安全底线； 在德国市政基础设施项目中，工商业储能方案精准平抑电力波动，保障市政关键负荷不间断供电，形成绿色、安全、高效的智慧用电闭环。 上述项目均采用同一套原生融合方案，在不同边界条件下完成并网验证并持续稳定运行，充分证明全栈架构的场景适应性。 本地化服务能力：全生命周期的责任闭环 硬件之外，服务是保障长期安全的另一基石。隆基位于西班牙马德里的光储技术服务中心已投入运营，全面覆盖欧洲区域项目，提供技术赋能、现场运维、故障响应、伙伴培训等全维度服务，实现本地需求快速响应与问题就地解决。同时，欧洲光储技术创新中心正在加速布局，将形成从前期方案设计、中期交付调试到后期运维升级的全生命周期责任闭环。 依托覆盖120个国家的服务网络及“2830规划”（2028年前建成30个全球本地服务中心），隆基正从“产品供应”转向“本地化能力扎根”。 目前，隆基在欧洲区的客户系统平均无故障运行时间（MTBF）达到8,500小时，售后问题平均闭环时间缩短至48小时以内。 全栈自研：以确定性消解不确定性 当行业仍在碎片化拼凑中争论责任归属，隆基已用超13GWh全球部署、零热失控记录及欧洲极端工况实证，给出明确回答：唯有全栈自研，才能从源头消除系统不确定性。隆基不仅满足于现行标准，更基于自研体系积累的运行数据与失效模式库，深度参与欧盟下一代储能安全标准的技术讨论，从规则执行者向技术贡献者延伸。 通过单一责任主体承担全系统安全责任，隆基将安全从成本要素转化为可量化的信任资产。其底层协议统一、5S部件深度整合及闭环服务体系，共同构成这一方案的技术基石-能源转型的确定性，不在别处，正在全栈贯通之处。 关于隆基 作为全球领先的绿色能源科技公司，隆基绿能聚焦科技创新，构建起光伏、储能与氢能三大核心引擎，为全球客户提供安全、经济、绿色的能源解决方案。公司倡导可持续发展，致力于让人人享有可负担的清洁能源。通过绿色电力、储能系统和氢能生产的有机衔接，实现发电、储电、用电全链条的清洁能源覆盖，构建真正普惠可达的清洁能源生态。 如欲了解更多信息，欢迎访问：https://www.longi.com/cn/ 上一条 下一条', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-09 00:00:00', '2026-07-13 22:58:17', '2026-07-13 23:55:49', 0, NULL, 'ENTERPRISE', 'EXTERNAL_NEWS', 'ENTERPRISE_SITE', '隆基绿能', 'https://www.longi.com/cn/news/intersolar-europe-2026-longi-one/', '48733dac0aaacbcb3d75bd336101cf155083106897da97dc3e00ff136c911e41', '2026-07-09 00:00:00', '2026-07-13 22:58:19', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (9, '隆基在德发布户用价值白皮书及AI数字化平台', '隆基在德发布户用价值白皮书及AI数字化平台 隆基新闻 2026.6.23 在能源转型持续深化的背景下，德国户用光伏市场正经历从“电力消费”向“价值创造”的角色跃迁。Intersolar Europe 2026期间，隆基与OSW集团在德国慕尼黑联合发布《德国屋顶价值评估白皮书》（Rooftop Valuation Report），系统评估德国户用光伏的经济潜力，并提出基于数字化工具的价值转化路径。 该白皮书指出，德国现有约2800万套私人住宅，其屋顶光伏年均节电潜力达45.44亿欧元，户用屋顶被视为尚未充分开发的重要…', '<h1>隆基在德发布户用价值白皮书及AI数字化平台</h1>  隆基新闻 2026.6.23\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul>\n<p>在能源转型持续深化的背景下，德国户用光伏市场正经历从“电力消费”向“价值创造”的角色跃迁。Intersolar Europe 2026期间，隆基与OSW集团在德国慕尼黑联合发布《德国屋顶价值评估白皮书》（Rooftop Valuation Report），系统评估德国户用光伏的经济潜力，并提出基于数字化工具的价值转化路径。</p>\n<p>该白皮书指出，德国现有约2800万套私人住宅，其屋顶光伏年均节电潜力达45.44亿欧元，户用屋顶被视为尚未充分开发的重要能源资产。报告通过对光照条件、屋顶结构、用电行为等维度的综合分析，为公众提供了一份可量化、可比较的投资参考框架。</p>\n<p>核心数据显示，即便在无政府补贴情境下，德国户用光伏系统依然具备良好的经济性。</p>\n<p>其中，巴伐利亚州与巴登-符腾堡州因光照资源与屋顶结构优势，投资回报率位居全国前列。报告进一步测算，典型德国家庭通过最大化自发自用比例，并结合储能系统与智能能源管理，光伏系统静态回收期约为9.4年，内部收益率（IRR）可达10.5%。上述数据为缓解市场观望情绪、增强业主投资信心提供了有力支撑。</p>\n<p>为推动白皮书成果从“理论评估”向“实际资产”转化，<strong>隆基与OSW同步发布AI数字化平台GreenSketch，并推出核心数字员工——AI Agent Emily，标志着双方在AI渠道赋能方面实现重要突破。</strong>该平台具备以下三项核心能力：</p>\n<ul>\n <li><strong>快速建模：</strong>用户仅需输入邮编，Emily即可基于卫星影像，在数分钟内生成高精度3D建筑模型，显著降低现场勘测门槛；</li>\n <li><strong>智能评估：</strong>系统自动分析屋顶坡度、阴影遮挡及本地气象数据，输出精细化GIS地理信息报告；</li>\n <li><strong>硬件联动：</strong>平台内嵌隆基EcoLife等高效组件的真实性能参数，确保收益预测与实际发电表现高度一致，增强长期回报的可信度。</li>\n</ul>\n<p>此次《德国屋顶价值评估白皮书》发布与GreenSketch平台上线，是隆基在德国市场推进“数字化能源解决方案”战略的关键举措。</p>\n<p>通过AI技术降低专业服务门槛，以精准数据构建用户信任，隆基正携手合作伙伴，推动德国户用屋顶资源向高效、透明、可持续的绿色能源系统转化，进一步释放其在能源转型中的经济与环境价值。</p>\n<p><strong>关于隆基</strong></p>\n<p>作为全球领先的绿色能源科技公司，隆基绿能聚焦科技创新，构建起光伏、储能与氢能三大核心引擎，为全球客户提供安全、经济、绿色的能源解决方案。公司倡导可持续发展，致力于让人人享有可负担的清洁能源。通过绿色电力、储能系统和氢能生产的有机衔接，实现发电、储电、用电全链条的清洁能源覆盖，构建真正普惠可达的清洁能源生态。</p>\n<p>如欲了解更多信息，欢迎访问：<a href=\"https://www.longi.com/cn/\" target=\"_blank\" rel=\"noopener noreferrer\">https://www.longi.com/cn/</a></p>\n<ul>\n <li></li>\n <li></li>\n <li></li>\n</ul> <a href=\"https://www.longi.com/cn/news/world-economic-forum-2026/\" rel=\"noopener noreferrer\" target=\"_blank\"> 上一条 </a> <a href=\"https://www.longi.com/cn/news/longi-bmw-berlin-marathon-2026/\" rel=\"noopener noreferrer\" target=\"_blank\"> 下一条 </a>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-06-23 00:00:00', '2026-07-13 22:58:17', '2026-07-14 18:36:44', 0, NULL, 'ENTERPRISE', 'EXTERNAL_NEWS', 'ENTERPRISE_SITE', '隆基绿能', 'https://www.longi.com/cn/news/greensketch/', 'a49095d1fac370a2c5025b827b85b6b624fe784f72facdb1eb8d63907deb870e', '2026-06-23 00:00:00', '2026-07-14 18:36:57', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (10, '关于2026年5月全国新增建档立卡新能源发电（不含户用光伏）项目情况的公告', '目录项的基本信息 公开事项名称: 关于2026年5月全国新增建档立卡新能源发电（不含户用光伏）项目情况的公告 索引号: 000019705/2026-000072 主办单位: 国家能源局 制发日期: 2026-06-22   关于2026年5月全国新增建档立卡新能源发电（不含户用光伏）项目情况的公告   2026年5月，全国新增建档立卡新能源发电（不含户用光伏）项目共6173个，其中风电项目27个，光伏发电项目6136个（集中式光伏发电项目39个，工商业分布式光伏发电项目6097个），生物质发电项目10个。风电、集…', '<table>\n <tbody>\n  <tr>\n   <td>目录项的基本信息</td>\n  </tr>\n </tbody>\n</table>\n<table>\n <tbody>\n  <tr>\n   <td>公开事项名称:</td>\n   <td colspan=\"3\">关于2026年5月全国新增建档立卡新能源发电（不含户用光伏）项目情况的公告</td>\n  </tr>\n  <tr>\n   <td>索引号:</td>\n   <td>000019705/2026-000072</td>\n   <td>主办单位:</td>\n   <td>国家能源局</td>\n  </tr>\n  <tr>\n   <td>制发日期:</td>\n   <td colspan=\"3\">2026-06-22</td>\n  </tr>\n </tbody>\n</table>\n<table>\n <tbody>\n  <tr>\n   <td>&nbsp;</td>\n  </tr>\n </tbody>\n</table>\n<table>\n <tbody>\n  <tr>\n   <td>\n    <p><strong>  关于2026年5月全国新增建档立卡新能源发电（不含户用光伏）项目情况的公告</strong></p>\n    <p>  2026年5月，全国新增建档立卡新能源发电（不含户用光伏）项目共6173个，其中风电项目27个，光伏发电项目6136个（集中式光伏发电项目39个，工商业分布式光伏发电项目6097个），生物质发电项目10个。风电、集中式光伏发电、生物质发电项目清单见附件，工商业分布式光伏发电项目清单详见国家可再生能源发电项目信息管理平台网站（网址https://jdlk.renewable.org.cn/card-info-sheet/）。</p>\n    <p><strong>2026年5月全国新增建档立卡新能源发电项目情况</strong></p>\n    <table>\n     <tbody>\n      <tr>\n       <td>\n        <p><strong>地区</strong></p></td>\n       <td>\n        <p><strong>风电</strong></p></td>\n       <td>\n        <p><strong>集中式光伏发电</strong></p></td>\n       <td>\n        <p><strong>工商业分布式</strong></p>\n        <p><strong>光伏发电</strong></p></td>\n       <td>\n        <p><st