INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (11, '国家能源局组织召开全国可再生能源电力开发建设月度（6月）调度视频会', '  近日，国家能源局召开全国可再生能源电力开发建设月度（6月）调度视频会。国家能源局党组成员、副局长万劲松出席会议并讲话。   会议总结了2026年1—4月全国可再生能源发展总体情况，听取3月调度会提出的意见建议落实情况，分析可再生能源发展面临的形势和问题，提出了下一步工作要求。   会议指出，2026年1—4月，我国新能源和可再生能源发展总体保持良好态势。截至4月底，可再生能源发电装机突破24亿千瓦，占全国电力总装机的60.5%；新增装机7516万千瓦，占全部新增装机的70.7%；发电量1.2万亿千瓦时，占全社会…', '<p>  近日，国家能源局召开全国可再生能源电力开发建设月度（6月）调度视频会。国家能源局党组成员、副局长万劲松出席会议并讲话。</p>\n<p>  会议总结了2026年1—4月全国可再生能源发展总体情况，听取3月调度会提出的意见建议落实情况，分析可再生能源发展面临的形势和问题，提出了下一步工作要求。</p>\n<p>  会议指出，2026年1—4月，我国新能源和可再生能源发展总体保持良好态势。截至4月底，可再生能源发电装机突破24亿千瓦，占全国电力总装机的60.5%；新增装机7516万千瓦，占全部新增装机的70.7%；发电量1.2万亿千瓦时，占全社会用电量36.4%。其中，风电光伏装机累计并网19.11亿千瓦（风电6.61亿千瓦，光伏发电12.50亿千瓦），发电量合计8052亿千瓦时，占全社会用电量比重达到24.1%。可再生能源保供应、促转型的作用更加明显。</p>\n<p>  会议强调，为实现“十五五”良好开局，要重点做好七方面工作。<strong>一要进一步加大新能源并网消纳工作力度。</strong>以科学规划、有序建设为基础，全面提升电网接入、调节、调度、预测、跨区互济五大能力，多措并举提升新能源并网消纳水平。<strong>二要积极推进新能源就地就近消纳。</strong>各地、相关部门、企业及电力用户需协同推动绿电直连政策落地，充分释放新能源就地消纳潜力。<strong>三要加快推进项目建设。</strong>持续抓好大型风电光伏基地项目建设，抓紧办理开工前手续，合理安排工期，确保项目建设进展。<strong>四要扎实做好政策落地实施工作。</strong>立足政策初衷与长远发展，摸清实际情况，倾听企业诉求，在政策框架内妥善解决问题，结合地方实际精准落实政策要求。<strong>五要加快完善适应高比例新能源的市场机制。</strong>既要遵循市场价格波动规律，保障新能源企业收益稳定，也要合理拉开价格距离，依托价格信号带动储能发展，助力双碳目标落地。<strong>六要加快提升企业综合竞争能力。</strong>发电企业要掌握发、配、用全链条管理及绿电、碳核算等相关能力，向综合型主体转型，进一步提升决策水平，适应市场规则要求。<strong>七要加强工作统筹形成工作合力。</strong>地方能源主管部门要结合本地可再生能源发展指标、碳排放考核要求与当地的实际情况，统筹谋划推动各项政策有效落地。国家能源局派出机构要做好政策监督调度，发现问题及时提醒上报。</p>\n<p>  国家发展改革委、国家能源局有关司（局），各省（区、市）及新疆生产建设兵团能源主管部门，国家能源局派出机构，有关电网企业、发电企业，水电总院、电规总院、国家发展改革委能源研究所、中国水力发电工程学会、中国可再生能源学会风能专业委员会、中国光伏行业协会等单位有关负责同志参加会议。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-06-16 00:00:00', '2026-07-14 16:08:30', '2026-07-14 18:35:26', 0, NULL, 'INDUSTRY', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '国家能源局', 'https://www.nea.gov.cn/20260616/ab30f2b505764d13972ac14e7d3ffeed/c.html', '9b7b10fea27f13445ced3703d6d147e8abd0778d7675dbd10e56101e89ef9558', '2026-06-16 00:00:00', '2026-07-14 18:35:41', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
