r>\n     </tbody>\n    </table>\n    <p>&nbsp;</p>\n    <p><strong>附件：</strong></p>\n    <p>&nbsp;</p>\n    <p>国家能源局&nbsp;</p>\n    <p>2026年3月4日&nbsp;</p></td>\n  </tr>\n </tbody>\n</table>\n<table>\n <tbody>\n  <tr>\n   <td>&nbsp;</td>\n  </tr>\n </tbody>\n</table>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-03-04 00:00:00', '2026-07-14 16:08:31', '2026-07-14 18:35:27', 0, NULL, 'POLICY', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '国家能源局', 'https://www.nea.gov.cn/20260304/00841099b2d543099f5c957cb3f85b42/c.html', '1833a951c6d03c5698373467720b0daf101e2ecc7e874335204a9c91ee9025db', '2026-03-04 00:00:00', '2026-07-14 18:35:41', 1, NULL, NULL, NULL, NULL, NULL, '2026年1月全国新增建档立卡新能源发电项目（不含分布式光伏）', 'DOCX', 'https://www.nea.gov.cn/20260304/00841099b2d543099f5c957cb3f85b42/2026030400841099b2d543099f5c957cb3f85b42_4282e5296197874d4bae0b127626c88a80.docx');
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (16, '国家能源局组织召开全国可再生能源电力开发建设（1月）调度视频会', '  近日，国家能源局召开全国可再生能源电力开发建设（1月）调度视频会。国家能源局党组成员、副局长万劲松出席会议并讲话。   会议总结了2025年全国可再生能源发展总体情况，听取了上次月度调度会提出的意见建议落实情况，分析了可再生能源发展面临的形势和问题，部署了2026年重点工作。   会议指出，在全行业共同努力下，2025年全国可再生能源新增装机达到4.52亿千瓦，同比增长20.7%，约占新增装机的82.5%。截至2025年底，可再生能源总装机23.37亿千瓦，约占全国电力总装机的60%；可再生能源发电量3.99万…', '<p>  近日，国家能源局召开全国可再生能源电力开发建设（1月）调度视频会。国家能源局党组成员、副局长万劲松出席会议并讲话。</p>\n<p>  会议总结了2025年全国可再生能源发展总体情况，听取了上次月度调度会提出的意见建议落实情况，分析了可再生能源发展面临的形势和问题，部署了2026年重点工作。</p>\n<p>  会议指出，在全行业共同努力下，2025年全国可再生能源新增装机达到4.52亿千瓦，同比增长20.7%，约占新增装机的82.5%。截至2025年底，可再生能源总装机23.37亿千瓦，约占全国电力总装机的60%；可再生能源发电量3.99万亿千瓦时，占全社会用电量38.5%。2025年，全国新增并网风电、太阳能发电装机4.38亿千瓦（其中风电1.2亿千瓦，太阳能发电3.18亿千瓦），同比增长22.3%，再创历史新高；风电光伏累计并网装机达到18.4亿千瓦，历史性超过火电，占比47%；风光发电量合计2.3万亿千瓦时，约占全社会用电量的22%。无论从新增装机还是发电量看，2025年新能源发展均创历史新高。</p>\n<p>  会议强调，为实现“十五五”良好开局，要重点做好五方面工作。一是坚定发展信心，加强政策供给和执行。落实能源法要求，推动出台可再生能源消费最低比重目标制度政策文件，从消费侧压实重点用能行业、企业责任，进一步扩大可再生能源消费。二是加力扩大投资，抓好2026年一季度投资计划落实。聚焦促投资、稳增长，加快推进项目建设，有条件的推动尽早开工，为“十五五”开好局贡献新能源力量。三是积极探索创新，解决好消纳问题，促进新能源高质量发展。地方能源主管部门和企业要结合自身实际，利用好绿电直连、新能源集成融合发展等激励政策，积极探索新能源非电利用等新模式新业态，拓展更多应用场景，推动新能源就近就地消纳，提升新能源安全可靠替代能力。四是科学编制规划，充分发挥行业规划引领作用。科学编制国家可再生能源发展“十五五”规划，指导地方在编制规划过程中做好与国家规划的衔接，推动“十五五”期间可再生能源实现扩量提质、可靠替代。五是加强指导协调，解决行业发展面临的困难问题。国家发展改革委、国家能源局相关司（局）、地方能源主管部门、派出机构进一步加强工作指导，形成工作合力，积极协调解决政策落实和项目推进过程中遇到的困难问题，确保各项工作按既定节奏稳步推进。</p>\n<p>  国家发展改革委、国家能源局有关司（局），各省（区、市）及新疆生产建设兵团能源主管部门，国家能源局派出机构，有关电网企业、发电企业，水电总院、电规总院、国家发展改革委能源研究所、中国可再生能源学会风能专业委员会、中国光伏行业协会、中国水力发电工程学会等单位有关负责同志参加会议。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-02-12 00:00:00', '2026-07-14 16:08:31', '2026-07-14 18:35:27', 0, NULL, 'INDUSTRY', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '国家能源局', 'https://www.nea.gov.cn/20260212/7778cf9907bf4eabb0e73a939ff2ade2/c.html', '9768129604de6497d1e0738ca67378789dec078e3148bae06d5b1d0235736add', '2026-02-12 00:00:00', '2026-07-14 18:35:41', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (17, '2025年可再生能源并网运行情况', '  2025年，国家能源局以习近平新时代中国特色社会主义思想为指导，深入学习贯彻党的二十大和二十届历次全会精神，锚定碳达峰碳中和目标，深入践行“四个革命、一个合作”能源安全新战略，推动构建起全球最大、发展最快的可再生能源体系，超额完成“十四五”非化石能源消费目标任务，为加快构建新型能源体系和建设能源强国提供了有力支撑。   可再生能源装机规模再创新高，规模占比稳步提升。可再生能源装机占比超六成，其中风电、太阳能发电新增装机超4.3亿千瓦，累计装机占比接近一半，历史性超过火电。2025年，全国可再生能源发电新增装机4…', '<p>  2025年，国家能源局以习近平新时代中国特色社会主义思想为指导，深入学习贯彻党的二十大和二十届历次全会精神，锚定碳达峰碳中和目标，深入践行“四个革命、一个合作”能源安全新战略，推动构建起全球最大、发展最快的可再生能源体系，超额完成“十四五”非化石能源消费目标任务，为加快构建新型能源体系和建设能源强国提供了有力支撑。</p>\n<p>  <strong>可再生能源装机规模再创新高，规模占比稳步提升。</strong>可再生能源装机占比超六成，其中风电、太阳能发电新增装机超4.3亿千瓦，累计装机占比接近一半，历史性超过火电。2025年，全国可再生能源发电新增装机4.52亿千瓦，同比增长21%，占全国电力新增装机的83%。其中，水电新增1215万千瓦，风电新增1.2亿千瓦，太阳能发电新增3.18亿千瓦，生物质发电新增151万千瓦。截至2025年底，全国可再生能源装机总量达23.4亿千瓦，同比增长24%，约占全国电力总装机的60%。其中，水电装机4.5亿千瓦，风电装机6.4亿千瓦，太阳能发电装机12亿千瓦，生物质发电装机0.47亿千瓦。风电、太阳能发电装机合计18.4亿千瓦，占比47%。</p>\n<p>  <strong>可再生能源发电量持续增长，绿色低碳发展提速。</strong>全社会用电量中每10度电有近4度是绿电，全社会用电增量全部由可再生能源新增发电量提供。2025年，全国可再生能源发电量3.99万亿千瓦时，同比增长15%，约占全部发电量的38%，超过同期第三产业用电量（19942亿千瓦时）与城乡居民生活用电量（15880亿千瓦时）之和。2025年，全国新增可再生能源发电量5193亿千瓦时，已经覆盖全社会用电增量（5161亿千瓦时）。</p>\n<p> <strong> （一）水电建设和运行情况。</strong>2025年，全国新增水电装机容量1215万千瓦，其中常规水电新增467万千瓦，抽水蓄能新增748万千瓦。截至2025年12月，全国水电累计装机容量达4.5亿千瓦，其中常规水电3.8亿千瓦，抽水蓄能6594万千瓦。</p>\n<p>  2025年，全国水电发电量1.46万亿千瓦时，全国规模以上水电平均利用小时数为3367小时。</p>\n<p>  <strong>（二）风电建设和运行情况。</strong>2025年，全国风电新增装机容量1.2亿千瓦，同比增长51%，其中陆上风电新增1.1亿千瓦，海上风电新增659万千瓦。从新增装机分布看，“三北”地区占全国新增装机的79%。</p>\n<p>  截至2025年12月，全国风电累计并网容量达到6.4亿千瓦，同比增长23%，其中陆上风电5.9亿千瓦，海上风电0.47亿千瓦。</p>\n<p>  2025年，全国风电发电量1.13万亿千瓦时，同比增长13%；全国风电平均利用率94%。</p>\n<p>  <strong>（三）光伏发电建设和运行情况。</strong>2025年，全国光伏新增装机3.17亿千瓦，同比增长14%，其中集中式光伏新增1.64亿千瓦，分布式光伏新增1.53亿千瓦。</p>\n<p>  截至2025年12月，全国光伏发电装机容量达到12亿千瓦，同比增长35%，其中集中式光伏6.7亿千瓦，分布式光伏5.3亿千瓦。</p>\n<p>  2025年，全国光伏发电量1.17万亿千瓦时，同比增长40%；全国光伏发电利用率95%。</p>\n<p>  <strong>（四）生物质发电建设和运行情况。</strong>2025年，全国生物质发电新增装机151万千瓦。截至2025年12月，全国生物质发电装机容量达到4743万千瓦，同比增长3%。生物质发电量2247亿千瓦时，同比增长7%。</p>\n<p>  <strong>（五）光热发电建设和运行情况。</strong>2025年，全国光热发电新增装机94万千瓦，同比增长203%。截至2025年12月，全国光热发电装机容量达到182万千瓦，同比增长107%。光热发电量16亿千瓦时，同比增长32%。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-02-12 00:00:00', '2026-07-14 16:08:32', '2026-07-14 18:35:28', 0, NULL, 'INDUSTRY', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '国家能源局', 'https://www.nea.gov.cn/20260212/742b8c6a078347b0b39de676c05c5d58/c.html', '31638d36718fa0c6807426781b8df986acc871cec64db302a36b6f2996fdbbf8', '2026-02-12 00:00:00', '2026-07-14 18:35:41', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (18, '暴雨过后，光伏电站应先检查什么', '从积水、支架、电缆和监控数据四个方面完成雨后基础巡检。', '暴雨停止并确认现场安全后，建议先检查站区排水和设备基础是否积水，再查看支架、围栏及组件是否出现松动或破损。重点排查汇流箱、逆变器、电缆接头和穿管位置的进水痕迹，不要在积水未排除时带电操作。最后结合监控曲线核对组串电流、绝缘告警和通信状态，对异常点位做好记录并交由具备资质的人员处理。本文为光伏智云平台整理的通用巡检建议，具体操作应遵循设备说明书和电站安全制度。', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-14 16:25:19', '2026-07-14 16:25:19', '2026-07-14 16:25:19', 0, NULL, 'PLATFORM', 'PLATFORM_ARTICLE', 'PLATFORM', '光伏智云平台', NULL, 'platform-guide-rain-inspection-v1', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (19, '高温天气下的组件效率与运行检查', '高温会影响组件输出，巡检时应同时关注散热、遮挡和电气连接。', '组件温度升高时，实际输出功率通常会受到温度系数影响。运维人员可对照环境温度、组件背板温度和同组串功率，识别异常温升或输出偏差。检查时应保持逆变器通风通道畅通，及时清理影响散热的杂物，并关注接头、线缆和配电设备是否存在过热迹象。不要仅凭瞬时功率判断设备故障，应结合辐照度、历史曲线和同类设备表现综合分析。', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-14 16:25:19', '2026-07-14 16:25:19', '2026-07-14 16:25:19', 0, NULL, 'PLATFORM', 'PLATFORM_ARTICLE', 'PLATFORM', '光伏智云平台', NULL, 'platform-guide-high-temperature-v1', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (20, '强对流天气前后的电站安全检查要点', '针对大风、雷电和短时强降雨，提前核对固定、排水与防雷设施。', '强对流天气来临前，应确认组件压块、支架连接、屋面附着物和临时设施是否牢固，检查排水沟、落水口及站区通道是否畅通。雷雨期间避免开展露天电气作业。天气结束后，优先检查组件破损、支架位移、防雷接地、箱体密封和通信中断情况；发现异响、焦味、明显变形或绝缘告警时，应按照电站应急流程隔离风险区域并安排专业人员复核。', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-14 16:25:19', '2026-07-14 16:25:19', '2026-07-14 16:25:19', 0, NULL, 'PLATFORM', 'PLATFORM_ARTICLE', 'PLATFORM', '光伏智云平台', NULL, 'platform-guide-convective-weather-v1', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (21, '地质灾害风险地区的光伏运维注意事项', '山地电站应把边坡、排水、道路和基础变形纳入日常风险巡查。', '位于山地、沟谷或地质灾害易发区域的电站，应持续关注降雨预报和属地灾害预警。巡检重点包括边坡裂缝、落石、排水冲刷、道路沉降、基础外露和支架倾斜。连续降雨或收到地质灾害预警时，应减少非必要现场作业，避免人员进入陡坡、沟口和可能发生滑坡泥石流的区域。异常情况应及时留存位置和影像记录，并联系属地管理部门或专业单位评估。', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-14 16:25:19', '2026-07-14 16:25:19', '2026-07-14 16:25:19', 0, NULL, 'PLATFORM', 'PLATFORM_ARTICLE', 'PLATFORM', '光伏智云平台', NULL, 'platform-guide-geological-risk-v1', NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (22, '国家防灾减灾救灾委员会启动国家四级救灾应急响应 指导辽宁做好暴雨洪涝灾害救助工作', '国家防灾减灾救灾委员会启动国家四级救灾应急响应 指导辽宁做好暴雨洪涝灾害救助工作 按照《国家自然灾害救助应急预案》，7月14日，国家防灾减灾救灾委员会针对辽宁省暴雨洪涝灾害，启动国家四级救灾应急响应，派出工作组赴灾区实地查看灾情，指导和协助地方做好受灾群众基本生活保障等救灾救助工作。', '<p>国家防灾减灾救灾委员会启动国家四级救灾应急响应</p>\n<p>指导辽宁做好暴雨洪涝灾害救助工作</p>\n<p>按照《国家自然灾害救助应急预案》，7月14日，国家防灾减灾救灾委员会针对辽宁省暴雨洪涝灾害，启动国家四级救灾应急响应，派出工作组赴灾区实地查看灾情，指导和协助地方做好受灾群众基本生活保障等救灾救助工作。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-14 15:01:00', '2026-07-14 16:35:53', '2026-07-14 18:35:26', 0, NULL, 'DISASTER', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '中华人民共和国应急管理部', 'https://www.mem.gov.cn/xw/yjglbgzdt/202607/t20260714_676447.shtml', 'dd2de80932ee0f1500b00a5143b8d92d5c790c1daf5d8670edcff21fdb0878a8', '2026-07-14 15:01:00', '2026-07-14 18:35:40', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (23, '国家防办向吉林紧急调拨中央防汛物资 支持做好防汛抢险工作', '7月13日，应吉林省防汛抗旱指挥部请求，国家防办会同国家粮食和储备局紧急调拨编织袋、复膜编织布、长丝土工布、网箱网兜、照明设备等4300余件中央防汛物资，支持吉林做好防汛抢险工作。', '<p>7月13日，应吉林省防汛抗旱指挥部请求，国家防办会同国家粮食和储备局紧急调拨编织袋、复膜编织布、长丝土工布、网箱网兜、照明设备等4300余件中央防汛物资，支持吉林做好防汛抢险工作。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-14 07:06:00', '2026-07-14 16:35:53', '2026-07-14 18:35:26', 0, NULL, 'DISASTER', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '中华人民共和国应急管理部', 'https://www.mem.gov.cn/xw/yjglbgzdt/202607/t20260714_676282.shtml', '7eaf01d7a0be90fb33ed3ffbd8377d7c14bd748a32ace11ed8c349e9e31dea92', '2026-07-14 07:06:00', '2026-07-14 18:35:40', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (24, '国家防办向辽宁调拨中央防汛物资 支持做好防汛抢险工作', '国家防办向辽宁调拨中央防汛物资 支持做好防汛抢险工作 7月13日，应辽宁省防汛抗旱指挥部请求，国家防办会同国家粮食和储备局紧急调拨复膜编织布等2600余件中央防汛物资，支持辽宁省做好防汛抢险工作。', '<p>国家防办向辽宁调拨中央防汛物资 支持做好防汛抢险工作</p>\n<p>7月13日，应辽宁省防汛抗旱指挥部请求，国家防办会同国家粮食和储备局紧急调拨复膜编织布等2600余件中央防汛物资，支持辽宁省做好防汛抢险工作。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-13 19:19:00', '2026-07-14 16:35:53', '2026-07-14 18:35:27', 0, NULL, 'DISASTER', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '中华人民共和国应急管理部', 'https://www.mem.gov.cn/xw/yjglbgzdt/202607/t20260713_676259.shtml', '25b8c10b9e94c96f7c786d16f41dbcbf97f8ee82b4f190e0da0b7b08573ebb0e', '2026-07-13 19:19:00', '2026-07-14 18:35:40', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (25, '国家防灾减灾救灾委员会办公室 应急管理部发布2026年上半年全国自然灾害情况', '国家防灾减灾救灾委员会办公室 应急管理部 发布2026年上半年全国自然灾害情况 近日，国家防灾减灾救灾委员会办公室会同有关成员单位，对2026年上半年全国自然灾害情况进行了会商分析。上半年，我国自然灾害以洪涝灾害、地质灾害、风雹灾害、地震灾害为主，干旱灾害、低温雨雪冰冻和雪灾等也有不同程度发生。据初步统计，各种自然灾害共造成全国1727.6万人次不同程度受灾，死亡失踪155人，紧急转移安置和需紧急生活救助58.7万人次，倒塌房屋1000余户近3400间，损坏房屋5.3万户10.5万间，农作物受灾面积1697.6千公…', '<p>国家防灾减灾救灾委员会办公室 应急管理部</p>\n<p>发布2026年上半年全国自然灾害情况</p>\n<p>近日，国家防灾减灾救灾委员会办公室会同有关成员单位，对2026年上半年全国自然灾害情况进行了会商分析。上半年，我国自然灾害以洪涝灾害、地质灾害、风雹灾害、地震灾害为主，干旱灾害、低温雨雪冰冻和雪灾等也有不同程度发生。据初步统计，各种自然灾害共造成全国1727.6万人次不同程度受灾，死亡失踪155人，紧急转移安置和需紧急生活救助58.7万人次，倒塌房屋1000余户近3400间，损坏房屋5.3万户10.5万间，农作物受灾面积1697.6千公顷，直接经济损失421.4亿元。</p>\n<p>上半年全国自然灾害主要特点有：</p>\n<p>一、灾害损失总体偏轻，5月因暴雨提前损失突出，呈现“南重北轻”</p>\n<p>上半年，自然灾害损失总体偏轻，因灾死亡失踪人数、倒塌房屋数量和直接经济损失较常年同期均值明显下降。从时间分布看，1－4月份，全国灾害形势较为平稳，未发生重大自然灾害；入汛后强降雨过程明显提前，导致洪涝和地质灾害形势严峻，5月份灾害损失突出，因灾死亡失踪人数和直接经济损失均占上半年总数的五成；6月份洪涝和地质灾害灾情偏轻。从地区分布看，西南、华中等地发生严重暴雨洪涝和地质灾害；西南、西北等地发生中强地震；东北、西南风雹影响突出。南方灾情明显重于北方，南方因灾死亡失踪人数和直接经济损失均占全国总数的八成，其中，贵州、湖南、重庆、湖北、广东等地受灾较重。从灾害种类看，洪涝和地质灾害损失最重，造成因灾死亡失踪人数和直接经济损失均占全灾种总数的八成。</p>\n<p>二、暴雨过程落区重叠、极端性强，西南华中地区洪涝和地质灾害灾情突出</p>\n<p>上半年，全国平均降水量284.1毫米，较常年同期偏多2.3%；共出现14次区域暴雨过程，均影响华南、江南或西南地区，落区高度重叠。其中，5月15日至20日的暴雨过程持续时间长、影响范围广、极端性强，强降雨过程发生时间明显提前。全国主要江河径流总量较常年同期偏多近1成，水位较常年同期总体偏高，22省（自治区、直辖市）315条河流发生超警以上洪水，其中49条超保、2条发生有实测资料以来最大洪水。强降雨引发洪涝和地质灾害造成较大损失，其中，贵州、湖南、重庆3省（直辖市）共74人死亡失踪，直接经济损失189.2亿元，分别占全国总数的59.7%和55.9%。洪涝和地质灾害共造成1132.6万人次不同程度受灾，死亡失踪124人，紧急转移安置和需紧急生活救助55.2万人次，倒塌房屋近2900间，损坏房屋4.2万间，农作物受灾面积852.1千公顷，直接经济损失338.7亿元。</p>\n<p>三、广西柳州、青海海西地震造成一定损失</p>\n<p>上半年，我国华北、华南、西部地区均有3级以上地震活动，大陆应力水平整体偏高；共发生5.0级以上地震10次，低于历史平均活动水平。其中，最大震级为6月16日青海海西6.3级地震，造成1人死亡，部分居民房屋、基础设施等受损；5月18日广西柳州市柳南区发生的2次5.2级地震震源浅，破坏力相对较强，叠加震区位于地下溶洞、地下河等地质构造较为发育的喀斯特地区，造成2人死亡，对当地部分自建房造成较大破坏；6月29日四川宜宾市高县发生5.5级地震，造成部分房屋受损，未造成人员死亡。相关地震灾害损失均正在进一步核查评估中。截至目前，地震灾害共造成广西、青海、云南等7省（自治区）34.2万人不同程度受灾，死亡3人，紧急转移安置2.3万人次。</p>\n<p>四、风雹灾害影响东北、西南地区，低温雨雪冰冻和雪灾总体偏轻</p>\n<p>上半年，全国共出现23次区域性强对流天气过程；5月下旬以来，受东北冷涡影响，东北、华北强对流频发。风雹灾害点多面广，主要影响我国东北、西南地区，对局地房屋、农作物、基础设施等造成损害，大风、雷电造成部分人员伤亡。其中，5月31日黑龙江哈尔滨、绥化等局地出现雷暴大风，造成9人死亡。风雹灾害共造成470.2万人次不同程度受灾，死亡24人，倒塌房屋300余间，损坏房屋4.3万间，农作物受灾面积644.6千公顷，直接经济损失66.5亿元。共有13次冷空气过程影响我国，较常年同期偏少，低温雨雪冰冻和雪灾偏轻发生，共造成41.3万人次不同程度受灾，死亡2人，农作物受灾面积36.6千公顷，直接经济损失2.8亿元。</p>\n<p>五、南北方旱情阶段性、区域性发展，目前大部地区已缓解</p>\n<p>上半年，全国平均气温9.0℃，较常年同期偏高1.1℃，为1961年以来历史同期最高。全国9677座重点水库蓄水总量较常年同期偏多1成。4月上旬，广西、云南、海南等地降水显著偏少、气温异常偏高，海南东部和广西中部局地出现旱情；受4月下旬降水过程影响，华南等地旱情解除。同期，华北、黄淮及内蒙古中部干旱短暂发展后解除。截至目前，旱情主要分布在内蒙古。干旱灾害共造成内蒙古、云南、海南等6省（自治区）47.6万人次不同程度受灾，因旱需生活救助人口1.6万人，农作物受灾面积160.4千公顷，直接经济损失6.4亿元。此外，有13次沙尘天气过程影响我国，较常年同期略偏多；其中，2月20日至23日的沙尘天气过程影响范围最广，未造成明显损失。</p>\n<p>六、森林草原火灾形势总体平稳，局地阶段性火灾多发</p>\n<p>1月至2月，受连续高温少雨天气影响，华南、西南部分地区森林火险等级持续攀升，广东、西藏等地火灾多发。4月份，内蒙古东部草原火险全月均处于高火险等级，相继发生5起草原火灾，且蒙方一侧草原火灾频频压境，边境火防控压力增大。据统计，上半年全国发生森林火灾59起，其中，广东26起，云南5起，辽宁、黑龙江、西藏各4起，四川、福建各3起，山东、江西、海南、陕西各2起，重庆、贵州各1起；发生草原火灾5起，均在内蒙古。均未造成人员伤亡。</p>\n<p>此外，上半年，我国沿海发生了2次温带风暴潮过程，近海海域发生了13次灾害性海浪过程，均未造成人员伤亡和明显经济损失。西藏发生多起野生动物伤人事件，造成2人死亡。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-13 17:05:00', '2026-07-14 16:35:53', '2026-07-14 18:35:27', 0, NULL, 'DISASTER', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '中华人民共和国应急管理部', 'https://www.mem.gov.cn/xw/yjglbgzdt/202607/t20260713_676243.shtml', '918bf13e5a9b28701239049ef4869e77cd904179fb05ba54959f2a2b5851ef78', '2026-07-13 17:05:00', '2026-07-14 18:35:40', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (26, '国家防灾减灾救灾委员会启动国家四级救灾应急响应 指导河北做好暴雨洪涝灾害救助工作', '国家防灾减灾救灾委员会启动国家四级救灾应急响应 指导河北做好暴雨洪涝灾害救助工作 按照《国家自然灾害救助应急预案》，7月13日，国家防灾减灾救灾委员会针对河北省暴雨洪涝灾害，启动国家四级救灾应急响应，派出工作组赴灾区实地查看灾情，指导和协助地方做好受灾群众基本生活保障等灾害救助工作。', '<p>国家防灾减灾救灾委员会启动国家四级救灾应急响应</p>\n<p>指导河北做好暴雨洪涝灾害救助工作</p>\n<p>按照《国家自然灾害救助应急预案》，7月13日，国家防灾减灾救灾委员会针对河北省暴雨洪涝灾害，启动国家四级救灾应急响应，派出工作组赴灾区实地查看灾情，指导和协助地方做好受灾群众基本生活保障等灾害救助工作。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-13 16:46:00', '2026-07-14 16:35:53', '2026-07-14 18:35:27', 0, NULL, 'DISASTER', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '中华人民共和国应急管理部', 'https://www.mem.gov.cn/xw/yjglbgzdt/202607/t20260713_676240.shtml', 'b8b80969dbd51653142a68f7144095b33bf3e37298348c55dd4c80410debafa8', '2026-07-13 16:46:00', '2026-07-14 18:35:40', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (27, '国家防办向天津、安徽调拨中央防汛物资 支持做好防汛抢险工作', '7月12日，应天津市、安徽省防汛抗旱指挥部请求，国家防总办公室会同国家粮食和储备局调拨编织袋、复膜编织布、橡皮舟、排涝设备、发电机等7500余件中央防汛物资，支持两省份做好防汛抢险工作。', '<p>7月12日，应天津市、安徽省防汛抗旱指挥部请求，国家防总办公室会同国家粮食和储备局调拨编织袋、复膜编织布、橡皮舟、排涝设备、发电机等7500余件中央防汛物资，支持两省份做好防汛抢险工作。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-12 19:53:00', '2026-07-14 16:35:54', '2026-07-14 18:35:27', 0, NULL, 'DISASTER', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '中华人民共和国应急管理部', 'https://www.mem.gov.cn/xw/yjglbgzdt/202607/t20260712_676083.shtml', '244952689e56db4bb4b24cad06f6c1053a642104d99ce9e23ef0607ac4827671', '2026-07-12 19:53:00', '2026-07-14 18:35:40', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (28, '国家防减救灾委办公室、应急管理部会同国家粮食和储备局调拨7万件中央救灾物资 支持浙江、天津、安徽等地 做好台风“巴威”救灾救助工作', '国家防减救灾委办公室、应急管理部会同国家粮食和储备局 调拨7万件中央救灾物资 支持浙江、天津、安徽等地 做好台风“巴威”救灾救助工作 7月12日，国家防灾减灾救灾委员会办公室、应急管理部针对台风“巴威”影响，根据浙江、天津、安徽等地防汛防台风救灾工作需要，会同国家粮食和物资储备局向浙江、天津、安徽调拨折叠床、毛巾被、夏凉被、褥子、家庭应急包等7万件中央救灾物资，全力支持做好受灾群众紧急转移安置和救灾救助工作。', '<p>国家防减救灾委办公室、应急管理部会同国家粮食和储备局</p>\n<p>调拨7万件中央救灾物资 支持浙江、天津、安徽等地</p>\n<p>做好台风“巴威”救灾救助工作</p>\n<p>7月12日，国家防灾减灾救灾委员会办公室、应急管理部针对台风“巴威”影响，根据浙江、天津、安徽等地防汛防台风救灾工作需要，会同国家粮食和物资储备局向浙江、天津、安徽调拨折叠床、毛巾被、夏凉被、褥子、家庭应急包等7万件中央救灾物资，全力支持做好受灾群众紧急转移安置和救灾救助工作。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-12 14:20:00', '2026-07-14 16:35:54', '2026-07-14 18:35:27', 0, NULL, 'DISASTER', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '中华人民共和国应急管理部', 'https://www.mem.gov.cn/xw/yjglbgzdt/202607/t20260712_676057.shtml', 'fac714f903f1485286969548cdee1dddbcc275569582da1bcaeeececb73068b3', '2026-07-12 14:20:00', '2026-07-14 18:35:40', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (29, '国家防灾减灾救灾委员会启动国家救灾应急响应 派出工作组指导浙江做好“巴威”台风灾害救助工作', '国家防灾减灾救灾委员会启动国家救灾应急响应 派出工作组指导浙江做好“巴威”台风灾害救助工作 按照《国家自然灾害救助应急预案》，7月12日，国家防灾减灾救灾委员会针对今年第9号台风“巴威”对浙江带来的严重影响，启动国家四级救灾应急响应，派出救灾工作组紧急赶赴灾区，指导协助地方做好受灾群众转移安置和基本生活保障等救灾救助工作。', '<p>国家防灾减灾救灾委员会启动国家救灾应急响应</p>\n<p>派出工作组指导浙江做好“巴威”台风灾害救助工作</p>\n<p>按照《国家自然灾害救助应急预案》，7月12日，国家防灾减灾救灾委员会针对今年第9号台风“巴威”对浙江带来的严重影响，启动国家四级救灾应急响应，派出救灾工作组紧急赶赴灾区，指导协助地方做好受灾群众转移安置和基本生活保障等救灾救助工作。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-12 10:50:00', '2026-07-14 16:35:54', '2026-07-14 18:35:27', 0, NULL, 'DISASTER', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '中华人民共和国应急管理部', 'https://www.mem.gov.cn/xw/yjglbgzdt/202607/t20260712_676039.shtml', '34d6109d70007a8cfa513a7bb82b46e3c625cf71214b26d371fac11fab769d98', '2026-07-12 10:50:00', '2026-07-14 18:35:40', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (30, '国家防总调整启动应急响应 派出工作组加强指导', '据气象部门预报，受今年第9号台风“巴威”及其输送水气影响，未来三天，北京、天津、安徽、江西、辽宁、黑龙江有大暴雨，局地特大暴雨，部分地区有短时强降雨，山洪和地质灾害、中小河流洪水以及城市内涝等灾害风险较高。根据《国家防汛抗旱应急预案》及有关规定，国家防总决定于7月11日20时将针对北京、天津、辽宁、安徽、江西的国家防总防汛四级应急响应提升至三级，启动针对黑龙江的防汛四级应急响应，派出国家防总办公室工作组赴北京协助指导防汛工作。', '<p>据气象部门预报，受今年第9号台风“巴威”及其输送水气影响，未来三天，北京、天津、安徽、江西、辽宁、黑龙江有大暴雨，局地特大暴雨，部分地区有短时强降雨，山洪和地质灾害、中小河流洪水以及城市内涝等灾害风险较高。根据《国家防汛抗旱应急预案》及有关规定，国家防总决定于7月11日20时将针对北京、天津、辽宁、安徽、江西的国家防总防汛四级应急响应提升至三级，启动针对黑龙江的防汛四级应急响应，派出国家防总办公室工作组赴北京协助指导防汛工作。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-11 22:47:00', '2026-07-14 16:35:54', '2026-07-14 18:35:27', 0, NULL, 'DISASTER', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '中华人民共和国应急管理部', 'https://www.mem.gov.cn/xw/yjglbgzdt/202607/t20260711_676026.shtml', '763c55e7832b78d973fa2e30e93b4ab3a46ad145d16bf376be6b03c5d3ade798', '2026-07-11 22:47:00', '2026-07-14 18:35:40', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (31, '应急管理部将针对河北的国家地质灾害四级应急响应提升至三级 针对安徽启动国家地质灾害四级应急响应', '应急管理部将针对河北的国家地质灾害 四级应急响应提升至三级 针对安徽启动国家地质灾害四级应急响应 据气象部门预测，受西南季风和台风“巴威”影响，安徽南部、河北中部和东北部等部分地区大暴雨，局地特大暴雨。经与自然资源部会商研判，安徽南部局地发生地质灾害风险高，河北东北部发生地质灾害风险很高。根据《国家突发地质灾害应急预案》及有关规定，应急管理部于7月11日将针对河北的国家地质灾害四级应急响应提升至三级，针对安徽启动国家地质灾害四级应急响应。 应急管理部要求，相关强降雨地区要切实做好地质灾害防范应对工作，压实地方防范应…', '应急管理部将针对河北的国家地质灾害 四级应急响应提升至三级 针对安徽启动国家地质灾害四级应急响应 据气象部门预测，受西南季风和台风“巴威”影响，安徽南部、河北中部和东北部等部分地区大暴雨，局地特大暴雨。经与自然资源部会商研判，安徽南部局地发生地质灾害风险高，河北东北部发生地质灾害风险很高。根据《国家突发地质灾害应急预案》及有关规定，应急管理部于7月11日将针对河北的国家地质灾害四级应急响应提升至三级，针对安徽启动国家地质灾害四级应急响应。 应急管理部要求，相关强降雨地区要切实做好地质灾害防范应对工作，压实地方防范应对主体责任，落实部门协同联动工作机制，密切监视雨情汛情和地质灾害灾情险情，加强会商研判和预警响应联动，做好救援队伍、物资和装备的准备，强化巡查排查和监测预警，坚决果断组织转移避险，确保应转尽转、应转早转，最大限度避免人员伤亡。 应急管理部维持针对浙江、福建的地质灾害三级应急响应，维持针对北京、天津、辽宁、吉林的地质灾害四级应急响应，应急管理部工作组持续在浙江指导防范应对工作。', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-11 21:57:00', '2026-07-14 16:35:54', '2026-07-14 17:16:41', 0, NULL, 'DISASTER', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '中华人民共和国应急管理部', 'https://www.mem.gov.cn/xw/yjglbgzdt/202607/t20260711_676025.shtml', 'a587ce079e6abdbb07c281fb83fbcbf1bff1b0235ac7443c84fb79970be05287', '2026-07-11 21:57:00', '2026-07-14 17:17:11', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `news` (`news_id`, `title`, `summary`, `content`, `cover_url`, `news_type`, `target_role`, `status`, `publisher_id`, `published_at`, `created_at`, `updated_at`, `deleted`, `cover_file_id`, `category`, `content_type`, `source_type`, `source_name`, `source_url`, `external_id`, `source_published_at`, `fetched_at`, `external_content`, `warning_level`, `warning_region`, `warning_agency`, `effective_at`, `expires_at`, `attachment_name`, `attachment_type`, `attachment_url`) VALUES (32, '国家防总将针对吉林的防汛四级应急响应提升至三级', '国家防总将针对吉林的防汛四级 应急响应提升至三级 受台风“巴威”影响，吉林出现持续性强降雨，松花江吉林段发生2026年第1号洪水，辉发河支流梅河发生有实测资料以来最大洪水。预计7月14日至15日，吉林强降雨仍将持续，中东部部分地区有大到暴雨，东部局地大暴雨，辉发河将全线超警，江河洪水、山洪和地质灾害、中小水库出险以及城市洪涝等灾害风险高，防汛抗洪形势严峻复杂。 根据《国家防汛抗旱应急预案》及有关规定，国家防总决定于7月14日16时将针对吉林的防汛四级应急响应提升至三级，前期派出的工作组正在一线协助指导。', '<p>国家防总将针对吉林的防汛四级</p>\n<p>应急响应提升至三级</p>\n<p>受台风“巴威”影响，吉林出现持续性强降雨，松花江吉林段发生2026年第1号洪水，辉发河支流梅河发生有实测资料以来最大洪水。预计7月14日至15日，吉林强降雨仍将持续，中东部部分地区有大到暴雨，东部局地大暴雨，辉发河将全线超警，江河洪水、山洪和地质灾害、中小水库出险以及城市洪涝等灾害风险高，防汛抗洪形势严峻复杂。</p>\n<p>根据《国家防汛抗旱应急预案》及有关规定，国家防总决定于7月14日16时将针对吉林的防汛四级应急响应提升至三级，前期派出的工作组正在一线协助指导。</p>', NULL, 'NEWS', 'ALL', 'PUBLISHED', NULL, '2026-07-14 17:23:00', '2026-07-14 18:35:26', '2026-07-14 18:35:26', 0, NULL, 'DISASTER', 'EXTERNAL_NEWS', 'GOVERNMENT_SITE', '中华人民共和国应急管理部', 'https://www.mem.gov.cn/xw/yjglbgzdt/202607/t20260714_676483.shtml', '0bc53f0c3042720744a8e5e2bd05dfbe726bddee2dce430efd76b99ff2579a6d', '2026-07-14 17:23:00', '2026-07-14 18:35:40', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
